<script setup lang="ts">
import {ref,computed} from 'vue'
import {quaternionMatrix,rotation6d,mv} from '../utils/learningMath'
const angle=ref(150),flip=ref(false),skew=ref(.5)
const q=computed(()=>[Math.cos(angle.value*Math.PI/360),0,0,Math.sin(angle.value*Math.PI/360)].map(v=>flip.value?-v:v)),R=computed(()=>quaternionMatrix(q.value)),a=computed(()=>[R.value[0][0],R.value[1][0],0]),b=computed(()=>[R.value[0][1]+skew.value*a.value[0],R.value[1][1]+skew.value*a.value[1],.2]),six=computed(()=>rotation6d([...a.value,...b.value]))
const end=(v:number[])=>[225+v[0]*110-v[2]*25,135-v[1]*100-v[2]*30]
</script>
<template><div class="lab-grid"><svg class="lab-svg" viewBox="0 0 510 265" role="img" aria-label="Orthogonalisation de deux vecteurs"><circle cx="225" cy="135" r="105" fill="none" stroke="#cbd5e1"/><g v-for="(p,i) in [a,b]" :key="i"><line x1="225" y1="135" :x2="end(p)[0]" :y2="end(p)[1]" :stroke="['#CF1C24','#F15A22'][i]" stroke-width="3" stroke-dasharray="6 3"/></g><g v-for="i in [0,1,2]" :key="i"><line x1="225" y1="135" :x2="end(six.map(r=>r[i]))[0]" :y2="end(six.map(r=>r[i]))[1]" :stroke="['#CF1C24','#218638','#087fa1'][i]" stroke-width="3"/><text :x="end(six.map(r=>r[i]))[0]+5" :y="end(six.map(r=>r[i]))[1]-5">e{{i+1}}</text></g><text x="30" y="260">Pointillés : vecteurs prédits ; traits : base orthonormée</text></svg><div class="lab-readout"><p>Quaternion [w, x, y, z]</p><p><strong>{{q.map(v=>v.toFixed(3)).join(' ; ')}}</strong></p><p>q et −q produisent la même rotation.</p><p>Représentation 6D : deux vecteurs, puis orthogonalisation.</p><p>Six valeurs pour représenter une rotation à <b>trois degrés de liberté</b>.</p></div></div><div class="lab-controls"><label>Angle<input aria-label="Angle rotation" v-model.number="angle" type="range" min="-180" max="180"/>{{angle}}°</label><label><input v-model="flip" aria-label="Signe quaternion" type="checkbox"/>Changer q en −q</label><label>Obliquité<input aria-label="Obliquité" v-model.number="skew" type="range" min="-1" max="1" step=".05"/></label></div></template>
